<?php
require dirname(__DIR__,2).'/app/admin_view.php';
$slug=preg_replace('/[^a-z0-9-]/','',(string)($_GET['slug']??''));
$titles=['social-ads'=>'Social Media Ads','music'=>'Music & Video Distro','verification'=>'Verification','web-dev'=>'Web & App Dev','account-mgmt'=>'Account Management','press'=>'Press Releases','smm'=>'Likes & Followers','numbers'=>'Virtual Numbers','bots'=>'Custom Bots','proxies'=>'Proxies'];
admin_header($slug,$titles[$slug]??'Service controller');
?>
<?php if($slug==='smm'): ?><div class="card"><a class="btn primary" href="/admin/providers">Provider connections, service sync & profit</a></div><?php endif; ?>
<div id="service-content"><div class="card"><p class="empty">Loading service controller…</p></div></div>
<script>
const slug=<?=json_encode($slug)?>,root=document.getElementById('service-content'),notice=document.getElementById('notice');let data=null,activeWebTab=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const escq=s=>String(s??'').replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\n/g,' ');
const money=n=>'€'+Number(n||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2});
const st=s=>`<span class="status ${String(s)==='processing'?'review':String(s)==='completed'?'done':esc(s)}">${esc(s)}</span>`;
function saveMarket(v){localStorage.setItem('tdcMarketplace',JSON.stringify(v))}
async function load(){try{const r=await fetch('/api/admin-service.php?slug='+encodeURIComponent(slug),{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to load this service.');data=d;document.getElementById('platform-balance').textContent=money(d.stats?.income||0);draw()}catch(e){root.innerHTML=`<div class="card"><p class="empty">${esc(e.message||'Unable to load service controller.')}</p></div>`}}
function draw(){const p=data.page,s=data.stats||{},orders=data.orders||[];document.getElementById('admin-page-title').textContent=p.name;document.getElementById('admin-page-sub').textContent='Orders, money made and service fulfillment';let html=`<div class="kpi-row"><div class="kpi"><div class="kpi-lbl">ORDERS PLACED</div><div class="kpi-val">${Number(s.total||0)}</div><div class="kpi-sub">All recorded orders</div></div><div class="kpi hot"><div class="kpi-lbl">MONEY MADE</div><div class="kpi-val grad">${money(s.income||0)}</div><div class="kpi-sub">After refunds</div></div><div class="kpi"><div class="kpi-lbl">PENDING / REVIEW</div><div class="kpi-val">${Number(s.pending||0)}</div><div class="kpi-sub">Needs admin action</div></div><div class="kpi"><div class="kpi-lbl">COMPLETED</div><div class="kpi-val">${Number(s.completed||0)}</div><div class="kpi-sub">Delivered orders</div></div></div>`;if(slug==='web-dev')html+=renderWeb();else if(slug==='music')html+=renderMusic();else html+=renderOrders(orders);html+=renderServiceControls();root.innerHTML=html}
function renderOrders(orders){return `<div class="card"><div class="card-hd"><h3>${esc(data.page.name)} orders</h3><span class="muted">Approve · complete · invoice</span></div><div class="table-wrap">${orders.length?`<table data-orders><thead><tr><th>ID</th><th>Client</th><th>Details</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${orders.map(o=>`<tr><td>#${o.id}<br><small class="muted">${esc(o.created_at)}</small></td><td><strong>${esc(o.customer)}</strong><br><small class="muted">${esc(o.email)}</small></td><td>${esc(o.description||o.service)}</td><td>${money(o.amount)}</td><td id="status-cell-${o.id}">${st(o.status)}</td><td><div class="actions"><button class="btn small orange" onclick="quickStatus(${o.id},'processing')" ${String(o.service_slug).startsWith('smm-p')?'disabled title="Updated automatically by provider"':''}>Approve</button><button class="btn small green" onclick="quickStatus(${o.id},'completed')" ${String(o.service_slug).startsWith('smm-p')?'disabled title="Updated automatically by provider"':''}>Complete</button><button class="btn small" onclick="makeInvoice('${o.id}','${escq(o.customer)}','${escq(o.service)}',${Number(o.amount)})">Invoice</button></div></td></tr>`).join('')}</tbody></table>`:'<p class="empty">No orders have been submitted for this service.</p>'}</div></div>`}
function renderServiceControls(){const p=data.page,services=data.services||[];return `<div class="two-col"><div class="card"><div class="card-hd"><h3>Service page controls</h3></div><div class="field"><label>Dashboard label</label><input id="page-name" value="${esc(p.name)}"></div><div class="field"><label>Dashboard description</label><textarea id="page-description">${esc(p.description||'')}</textarea></div><div class="field"><label>Dashboard icon</label><input id="page-icon" value="${esc(p.icon||'')}"></div><label class="muted"><input type="checkbox" id="page-active" ${p.active?'checked':''} style="width:auto"> Show this service on user dashboard</label><div style="margin-top:12px"><button class="btn primary" onclick="savePage()">Save service page</button></div></div><div class="card"><div class="card-hd"><h3>Catalog pricing</h3></div>${services.length?`<div class="table-wrap"><table><thead><tr><th>Item</th><th>Price</th><th>Active</th><th></th></tr></thead><tbody>${services.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br><small class="muted">${esc(x.slug)}</small></td><td><input class="input short" id="price-${x.id}" type="number" min="0" step="0.01" value="${Number(x.price).toFixed(2)}"></td><td><input type="checkbox" id="active-${x.id}" ${x.active?'checked':''}></td><td><button class="btn small" onclick="savePrice(${x.id})">Save</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No catalog items mapped.</p>'}</div></div>`}
function renderWeb(){const names=['All orders','Host my site','Buy domain','Custom develop','Publish app','Web templates','App templates','Marketplace'];return `<div class="card"><div class="card-hd"><h3>Web & App Development</h3><span class="muted">Whole vertical controller</span></div><div class="tabs">${names.map((n,i)=>`<button class="tab ${i===activeWebTab?'active':''}" onclick="webTab(${i})">${i+1} ${n}</button>`).join('')}</div><div id="web-tab-body">${renderWebTab(activeWebTab)}</div></div>`}
function webTab(i){activeWebTab=i;const body=document.getElementById('web-tab-body');document.querySelectorAll('.tabs .tab').forEach((b,j)=>b.classList.toggle('active',j===i));if(body)body.innerHTML=renderWebTab(i)}
function renderWebTab(i){const names=['All orders','Host my site','Buy domain','Custom develop','Publish app','Web templates','App templates','Marketplace'];if(i===7){const items=marketStore();return `<div class="kpi-row" style="margin-top:14px"><div class="kpi"><div class="kpi-lbl">MARKETPLACE ITEMS</div><div class="kpi-val">${items.length}</div></div><div class="kpi hot"><div class="kpi-lbl">MONEY MADE</div><div class="kpi-val grad">€0.00</div></div></div><div class="form-grid"><div class="field"><label>Name</label><input id="mp-name" placeholder="Template name"></div><div class="field"><label>Type</label><select id="mp-type"><option>Web template</option><option>App template</option></select></div><div class="field"><label>Price (€)</label><input id="mp-price" type="number" value="49.99"></div><div class="field"><label>Stack</label><input id="mp-stack" placeholder="Next.js, Stripe…"></div></div><div style="margin:12px 0"><button class="btn primary" onclick="publishTemplate()">Publish to marketplace</button></div><div class="table-wrap"><table><thead><tr><th>Template</th><th>Type</th><th>Price</th><th>Stack</th><th>Status</th></tr></thead><tbody>${items.map(m=>`<tr><td><strong>${esc(m.name)}</strong></td><td>${esc(m.type)}</td><td>${money(m.price)}</td><td>${esc(m.stack)}</td><td>${st('active')}</td></tr>`).join('')}</tbody></table></div>`}const orders=data.orders||[];const q=names[i].toLowerCase();let rows=i===0?orders:orders.filter(o=>(String(o.service)+' '+String(o.description)+' '+String(o.details)).toLowerCase().includes(q.split(' ')[0]));const made=rows.reduce((a,o)=>a+Number(o.amount||0),0);return `<div class="kpi-row" style="margin-top:14px"><div class="kpi"><div class="kpi-lbl">ORDERS PLACED</div><div class="kpi-val">${rows.length}</div></div><div class="kpi hot"><div class="kpi-lbl">MONEY MADE</div><div class="kpi-val grad">${money(made)}</div></div></div>${rows.length?`<div class="muted">${esc(names[i])} orders are also listed in the main order table below.</div>`:'<p class="empty">No matching orders in this tab yet.</p>'}`}
function publishTemplate(){const name=document.getElementById('mp-name').value.trim(),type=document.getElementById('mp-type').value,price=parseFloat(document.getElementById('mp-price').value)||0,stack=document.getElementById('mp-stack').value.trim();if(!name)return toast('Enter template name','info');const items=marketStore();items.unshift({name,type,price,stack});saveMarket(items);webTab(7);toast(name+' published')}
function musicDetails(o){try{return typeof o.details==='string'?(JSON.parse(o.details||'{}')||{}):(o.details||{})}catch{return {}}}
function musicTitle(o){const j=musicDetails(o);return j.release_title||j.title||o.description||'Untitled release'}
function musicArtist(o){const j=musicDetails(o);return j.artist||j.primary_artist||'—'}
function musicKind(o){const j=musicDetails(o);const k=String(j.release_kind||j.release_type||'single').toLowerCase();return k==='album'?'Album':k==='video'?'Video':'Single'}
function musicArtwork(o){const hit=(o.media||[]).find(m=>String(m.kind)==='artwork');return hit?hit.id:''}
function musicCover(o,size){const id=musicArtwork(o);return id?`<img src="/api/music-media.php?id=${encodeURIComponent(id)}&inline" alt="" loading="lazy" style="width:${size}px;height:${size}px;border-radius:9px;object-fit:cover;border:1px solid var(--border);flex:0 0 ${size}px">`:`<span style="width:${size}px;height:${size}px;border-radius:9px;display:grid;place-items:center;background:rgba(99,102,241,.12);border:1px solid var(--border);color:#a5b4fc;flex:0 0 ${size}px;font-size:${Math.round(size/3)}px">♪</span>`}
function renderMusic(){const orders=data.orders||[];const emails=[...new Set(orders.map(o=>String(o.email||'').toLowerCase()).filter(Boolean))].sort();return `<div class="card"><div class="card-hd"><h3>Music &amp; video distribution orders</h3><span class="muted">Complete · reject · invoice · delete</span></div><div class="search-row"><input id="music-email-search" class="input search" list="music-emails" placeholder="Search by client email…" autocomplete="off" oninput="filterMusicOrders()"><datalist id="music-emails">${emails.map(e=>`<option value="${esc(e)}"></option>`).join('')}</datalist></div><div class="table-wrap">${orders.length?`<table data-orders id="music-orders-table"><thead><tr><th>ID</th><th>Client</th><th>Details</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${orders.map(musicRow).join('')}</tbody></table>`:'<p class="empty">No music or video releases have been submitted yet.</p>'}</div><p class="muted" id="music-search-empty" style="display:none">No release matches that client email.</p></div><div id="music-detail"></div>`}
function musicRow(o){return `<tr data-email="${esc(String(o.email||'').toLowerCase())}" data-title="${esc(musicTitle(o).toLowerCase())}" style="cursor:pointer" onclick="openMusicOrder(${Number(o.id)})"><td><strong>#${Number(o.id)}</strong><br><small class="muted">${esc(String(o.created_at||'').slice(0,10))}</small></td><td><strong>${esc(o.customer)}</strong><br><small class="muted">${esc(o.email)}</small></td><td><div style="display:flex;gap:10px;align-items:center">${musicCover(o,44)}<div><strong>${esc(musicTitle(o))}</strong><div class="muted">${esc(musicArtist(o))}</div><span class="status active" style="margin-top:5px">${esc(musicKind(o))}</span></div></div></td><td>${money(o.amount)}</td><td id="status-cell-${o.id}">${st(o.status)}</td><td><div class="actions" onclick="event.stopPropagation()"><button class="btn small green" onclick="quickStatus(${Number(o.id)},'completed')">Complete</button><button class="btn small orange" onclick="rejectOrder(${Number(o.id)},${Number(o.amount)||0})">Reject</button><button class="btn small danger" onclick="deleteOrder(${Number(o.id)})">Delete</button><button class="btn small" onclick="makeInvoice('${Number(o.id)}')">Invoice</button></div></td></tr>`}
function filterMusicOrders(){const q=(document.getElementById('music-email-search')?.value||'').trim().toLowerCase();const rows=[...document.querySelectorAll('#music-orders-table tbody tr')];let shown=0;for(const row of rows){const hit=!q||row.dataset.email.includes(q)||row.dataset.title.includes(q);row.style.display=hit?'':'none';if(hit)shown++}const empty=document.getElementById('music-search-empty');if(empty)empty.style.display=rows.length&&!shown?'':'none'}
function openMusicOrder(id){const o=(data.orders||[]).find(x=>Number(x.id)===Number(id)),host=document.getElementById('music-detail');if(!o||!host)return;const j=musicDetails(o),outlets=Array.isArray(j.outlets)?j.outlets:[],tracks=Array.isArray(j.tracks)?j.tracks:[],files=o.media||[];const v=x=>x?esc(x):'<span class="muted">—</span>';const item=(label,value)=>`<div class="muted">${esc(label)}</div><div style="color:var(--text);overflow-wrap:anywhere">${value}</div>`;const filesHtml=files.length?files.map(f=>`<a class="btn small" style="margin:0 6px 6px 0" href="/api/music-media.php?id=${encodeURIComponent(f.id)}&inline" target="_blank" rel="noopener">${esc(f.kind)} · ${esc(f.original_name)}</a>`).join(''):'<p class="muted">No uploaded files.</p>';const outletsHtml=outlets.length?outlets.map(x=>`<span class="status active" style="margin:0 6px 6px 0">${esc(x)}</span>`).join(''):'<p class="muted">No stores recorded.</p>';const tracksHtml=tracks.length?`<div class="card"><div class="card-hd"><h3>Track list · ${tracks.length}</h3></div><ol style="margin:0;padding-left:18px;font-size:.73rem;line-height:1.9">${tracks.map(t=>`<li>${esc(typeof t==='string'?t:(t.title||'Untitled track'))}${t&&t.isrc?` <small class="muted">${esc(t.isrc)}</small>`:''}</li>`).join('')}</ol></div>`:'';host.innerHTML=`<div class="modal open" id="music-order-modal" onclick="if(event.target===this)closeMusicOrder()"><div class="modal-card" style="width:min(920px,100%)" role="dialog" aria-modal="true" aria-label="Release details"><div class="modal-top"><h3>Release #${Number(o.id)}</h3><button class="btn small" type="button" onclick="closeMusicOrder()">Close</button></div><div style="display:flex;gap:16px;align-items:flex-start;margin:16px 0 6px;flex-wrap:wrap">${musicCover(o,150)}<div style="min-width:220px;flex:1"><h2 style="margin:0 0 5px;font-size:1.12rem;letter-spacing:-.02em">${esc(musicTitle(o))}</h2><div class="muted" style="font-size:.78rem">${esc(musicArtist(o))}</div><div class="actions" style="margin-top:10px"><span class="status active">${esc(musicKind(o))}</span>${st(o.status)}</div></div></div><div class="two-col"><div class="card"><div class="card-hd"><h3>Release</h3></div><div style="display:grid;grid-template-columns:132px 1fr;gap:7px 12px;font-size:.72rem">${item('Order ID','#'+Number(o.id))}${item('Client',esc(o.customer))}${item('Email',esc(o.email))}${item('Amount',money(o.amount))}${item('Submitted',v(String(o.created_at||'').slice(0,16)))}${item('ISRC',v(j.isrc))}${item('UPC',v(j.upc))}${item('Genre',v(j.genre||(Array.isArray(j.genres)?j.genres.join(', '):'')))}${item('Language',v(j.language))}${item('Release date',v(j.release_date))}${item('Featured artists',v(j.featured_artists))}${item('Copyright',v(j.copyright))}${j.description?item('Description',esc(j.description)):''}</div></div><div class="card"><div class="card-hd"><h3>Stores &amp; files</h3></div><div style="margin-bottom:12px">${outletsHtml}</div><div class="section-label" style="margin:0 0 8px">Uploaded files</div><div>${filesHtml}</div></div></div>${tracksHtml}<div class="actions" style="margin-top:14px;justify-content:flex-end"><button class="btn small green" type="button" onclick="quickStatus(${Number(o.id)},'completed')">Complete</button><button class="btn small orange" type="button" onclick="rejectOrder(${Number(o.id)},${Number(o.amount)||0})">Reject</button><button class="btn small danger" type="button" onclick="deleteOrder(${Number(o.id)})">Delete</button><button class="btn small primary" type="button" onclick="closeMusicOrder()">Done</button></div></div></div>`}
function closeMusicOrder(){const m=document.getElementById('music-order-modal');if(m)m.remove()}
async function send(action,values){const r=await fetch('/api/admin-service.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':data.csrf},body:JSON.stringify({action,slug,...values})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to save changes.');return d}
async function quickStatus(id,status){try{await send('order_update',{id,status,note:''});toast(status==='completed'?'Order completed':status==='processing'?'Order approved':'Order '+status);await load()}catch(e){toast(e.message,'error')}}
async function rejectOrder(id,amount){if(!confirm('Reject order #'+id+'?'+(Number(amount)>0?' The €'+Number(amount).toFixed(2)+' fee is refunded to the client wallet.':'')))return;try{await send('order_update',{id,status:'rejected',note:''});toast('Order rejected');await load()}catch(e){toast(e.message,'error')}}
async function deleteOrder(id){if(!confirm('Delete order #'+id+' permanently?\n\nThe release report is removed, uploaded files stay with the client and any unrefunded fee is refunded. This cannot be undone.'))return;try{const r=await send('order_delete',{id});toast(r&&r.refunded?'Order deleted and fee refunded':'Order deleted');await load()}catch(e){toast(e.message,'error')}}
function savePage(){send('page_update',{name:document.getElementById('page-name').value,icon:document.getElementById('page-icon').value,description:document.getElementById('page-description').value,active:document.getElementById('page-active').checked}).then(()=>{toast('Service page saved');load()}).catch(e=>toast(e.message,'error'))}
function savePrice(id){send('service_update',{id,price:document.getElementById('price-'+id).value,active:document.getElementById('active-'+id).checked}).then(()=>{toast('Price saved');load()}).catch(e=>toast(e.message,'error'))}
load();
</script>
<script src="/assets/admin-service-master.js?v=20261017-music"></script><?php admin_footer(); ?>
